-- ===== 7. 自检SQL =====
-- 1. ReceivedQty与入库一致: 入库Qty-退货Qty=ReceivedQty
WITH InQty AS (SELECT pid.PurchaseOrderId,pid.ProductId,SUM(pid.Qty) AS InSum FROM Pur_PurchaseInDetail pid JOIN Pur_PurchaseIn pi ON pid.PurchaseInId=pi.Id WHERE pi.IsDeleted=0 GROUP BY pid.PurchaseOrderId,pid.ProductId),
RetQty AS (SELECT pi2.PurchaseOrderId,prd.ProductId,SUM(prd.Qty) AS RetSum FROM Pur_PurchaseReturnDetail prd JOIN Pur_PurchaseReturn pr ON prd.PurchaseReturnId=pr.Id JOIN Pur_PurchaseIn pi2 ON pr.PurchaseInId=pi2.Id WHERE pr.IsDeleted=0 GROUP BY pi2.PurchaseOrderId,prd.ProductId)
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: ReceivedQty matches In/Return' ELSE 'FAIL' END AS Check_ReceivedQty FROM Pur_PurchaseOrderDetail pod LEFT JOIN InQty i ON pod.PurchaseOrderId=i.PurchaseOrderId AND pod.ProductId=i.ProductId LEFT JOIN RetQty r ON pod.PurchaseOrderId=r.PurchaseOrderId AND pod.ProductId=r.ProductId WHERE pod.ReceivedQty != ISNULL(i.InSum,0)-ISNULL(r.RetSum,0);

-- 2. 无负Qty
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: No negative Qty' ELSE 'FAIL' END FROM Pur_PurchaseOrderDetail WHERE Qty<=0 OR ReceivedQty<0;

-- 3. 金额闭环: Amount=Qty*UnitPrice
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Detail Amount=Qty*UnitPrice' ELSE 'FAIL' END FROM Pur_PurchaseOrderDetail WHERE Amount!=ROUND(Qty*UnitPrice,2);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: InDetail Amount=Qty*UnitPrice' ELSE 'FAIL' END FROM Pur_PurchaseInDetail WHERE Amount!=ROUND(Qty*UnitPrice,2);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: RetDetail Amount=Qty*UnitPrice' ELSE 'FAIL' END FROM Pur_PurchaseReturnDetail WHERE Amount!=ROUND(Qty*UnitPrice,2);

-- 4. TotalAmount与明细一致
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: Order TotalAmount=SUM(Detail)' ELSE 'FAIL' END FROM Pur_PurchaseOrder po WHERE po.TotalAmount!=(SELECT ISNULL(SUM(pod.Amount),0) FROM Pur_PurchaseOrderDetail pod WHERE pod.PurchaseOrderId=po.Id);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: In TotalAmount=SUM(Detail)' ELSE 'FAIL' END FROM Pur_PurchaseIn pi WHERE pi.TotalAmount!=(SELECT ISNULL(SUM(pid.Amount),0) FROM Pur_PurchaseInDetail pid WHERE pid.PurchaseInId=pi.Id);

-- 5. 时间顺序
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: OrderDate<InDate' ELSE 'FAIL' END FROM Pur_PurchaseIn pi JOIN Pur_PurchaseOrder po ON pi.PurchaseOrderId=po.Id WHERE pi.InDate<po.OrderDate;

-- 6. 状态统计
SELECT 'INFO' AS Check6, Status, COUNT(*) AS Cnt FROM Pur_PurchaseOrder WHERE IsDeleted=0 GROUP BY Status ORDER BY Status;

-- 7. 入库单状态
SELECT 'INFO' AS Check7, Status, COUNT(*) AS Cnt FROM Pur_PurchaseIn WHERE IsDeleted=0 GROUP BY Status ORDER BY Status;

